const OR_KEY = "YOUR_OPENROUTER_API_KEY";
const SYSTEM_PROMPT = "Tu es un expert en qualification de leads LinkedIn B2B pour une offre d'automatisation IA (Client Acquisition OS) destinee specifiquement a des independants et micro-equipes (1 a 4 personnes) exercant comme consultants, formateurs ou coachs dans les secteurs IA, tech, digital ou marketing, en France (francophones uniquement).\\n\\nQualifie OUI uniquement si la personne est independante, fondatrice ou dirigeante d'une structure de 1 a 4 personnes maximum, active en tant que consultant/formateur/coach dans l'IA, la tech, le digital ou le marketing.\\n\\nQualifie NON si : simple salarie sans pouvoir de decision, etudiant, structure de plus de 4 personnes, hors sujet (pas IA/tech/digital/marketing), profil visiblement en recherche d'emploi, activite hors du champ consultant/formateur/coach.\\n\\nReponds UNIQUEMENT en JSON strict, sans texte autour : {\\\"icp\\\": \\\"oui\\\" ou \\\"non\\\", \\\"raison\\\": \\\"1 phrase courte en francais expliquant pourquoi\\\"}";

async function classify(p) {
  const bio = (p.headline || '') + ((p.currentPosition && p.currentPosition[0] && p.currentPosition[0].description) ? ' | ' + p.currentPosition[0].description : '');
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { 'Authorization': 'Bearer ' + OR_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'anthropic/claude-haiku-4.5',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: 'Name: ' + (p.firstName || '') + ' ' + (p.lastName || '') + '\nBio: ' + bio }
        ],
        temperature: 0.1,
        max_tokens: 150
      }),
      json: true,
    });
    const content = (resp.choices && resp.choices[0] && resp.choices[0].message.content) || '';
    const match = content.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      return { icp: (parsed.icp || '').toLowerCase().trim() === 'oui' ? 'oui' : 'non', raison: parsed.raison || '' };
    }
  } catch (e) {}
  return { icp: 'non', raison: '' };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const countryCode = (p.location && p.location.countryCode || '').toUpperCase();
  if (countryCode && countryCode !== 'FR') continue;
  const result = await classify.call(this, p);
  if (result.icp !== 'oui') continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const bio = (p.headline || '') + (pos.description ? ' | ' + pos.description : '');
  out.push({
    json: {
      id: p.id,
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || '',
      bio: bio,
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      icpMatch: 'oui',
      raisonIcp: result.raison,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

