      body: { chat_id: TG_CHAT, text: 'Mathias Chow : echec envoi demande de connexion pour ' + (lead.name || lead.linkedinUrl || lead.id) + ' - raison: ' + ($input.item.json._inviteSkippedReason || 'inconnue') },
      json: true,
    });
  } catch (e) {}
}
return [{ json: $input.item.json }];

// Exclut tout profil signalant "Open to Work" — structure (badge Apify) ou texte (headline/summary/about).
function isOpenToWork(p) {
  if (p == null) return false;
  if (p.openToWork === true || p.open_to_work === true || p.isOpenToWork === true) return true;
  if (Array.isArray(p.badges) && p.badges.some(b => /open.?to.?work/i.test(String(b)))) return true;

  const fields = [p.headline, p.summary, p.about, p.title];
  const text = fields.filter(Boolean).join(' ').toLowerCase();
  const patterns = [
    /open\s*to\s*work/i,
    /#opentowork/i,
    /ouvert(e)?\s+aux\s+opportunit/i,
    /\u00e0\s+l['\u2019]\u00e9coute\s+du\s+march/i,
    /en\s+recherche\s+d['\u2019]emploi/i,
    /disponible\s+imm\u00e9diatement/i,
    /recherche\s+active(?:ment)?\s+un\s+poste/i,
  ];
  return patterns.some(re => re.test(text));
}

const items = $input.all();
return items.filter(item => !isOpenToWork(item.json));

const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const accountId = "6oH8b0a4QK2d9u9QOiL4Sg";
const searchQuery = "consultant formateur coach intelligence artificielle automatisation IA independant";
const targetAccountName = "Mathias Chow";

function parseWorkDurationMonths(exp) {
  if (!exp || !exp.start) return 0;
  const start = new Date(exp.start);
  const end = exp.end ? new Date(exp.end) : new Date();
  if (isNaN(start.getTime())) return 0;
  const months = (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth());
  return Math.max(months, 0);
}
function durationLabel(months) {
  const yr = Math.floor(months / 12);
  const mo = months % 12;
  let s = '';
  if (yr > 0) s += yr + ' yr ';
  if (mo > 0) s += mo + ' mo';
  return s.trim();
}

// Persistent pagination: advance through search result pages across daily runs
// instead of always re-fetching page 1 (which returned the same leads every time).
const staticData = $getWorkflowStaticData('global');
const searchCursor = staticData._searchCursor || null;

let searchResults = [];
let nextCursor = null;
try {
  const url = base + '/api/v1/linkedin/search?account_id=' + accountId + (searchCursor ? '&cursor=' + encodeURIComponent(searchCursor) : '');
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
    body: { api: 'classic', category: 'people', keywords: searchQuery },
    json: true,
  });
  searchResults = (resp.items || []).filter(i => i.type === 'PEOPLE').slice(0, 40);
  nextCursor = resp.cursor || null;
  // If a page returns nothing (end of results), loop back to the first page next time.
  if (searchResults.length === 0 && searchCursor) {
    staticData._searchCursor = null;
  } else {
    staticData._searchCursor = nextCursor;
  }
} catch (e) {
  // On a search error (e.g. stale/invalid cursor), reset to page 1 for the next run.
  staticData._searchCursor = null;
  return [];
}

const out = [];
for (const person of searchResults) {
  let profile = null;
  try {
    profile = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/api/v1/users/' + encodeURIComponent(person.id) + '?account_id=' + accountId + '&linkedin_sections=experience',
      headers: { 'X-API-KEY': key },
      json: true,
    });
  } catch (e) {
    continue;
  }
  if (!profile) continue;

  const exp = (profile.work_experience && profile.work_experience[0]) || {};
  const months = parseWorkDurationMonths(exp);

  out.push({
    json: {
      id: profile.provider_id,
      firstName: profile.first_name || '',
      lastName: profile.last_name || '',
      linkedinUrl: 'https://www.linkedin.com/in/' + (profile.public_identifier || ''),
      headline: profile.headline || '',
      followerCount: profile.follower_count || 0,
      currentPosition: [{
        position: exp.position || '',
        description: exp.description || '',
        duration: durationLabel(months),
        employmentType: exp.status || '',
        companyName: exp.company || '',
        companyLinkedinUrl: exp.company_id ? ('https://www.linkedin.com/company/' + exp.company_id) : '',
      }],
      targetAccountName: targetAccountName,
      targetAccountId: accountId,
    }
  });
}
return out;

